<script>function setAll(v){document.querySelectorAll('.attendance-select').forEach(x=>x.value=v);updateCounts()}function updateCounts(){const c={Present:0,Absent:0,Late:0,Leave:0};document.querySelectorAll('.attendance-select').forEach(x=>c[x.value]++);document.getElementById('countSummary').textContent=`Present ${c.Present} · Absent ${c.Absent} · Late ${c.Late} · Leave ${c.Leave}`}document.getElementById('studentSearch').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.attendance-row').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(q)?'':'none')});updateCounts();</script>
